#include <iostream>
#include <cmath>
int main() {
  int a = 10, b = 5, c = 2;
  int result1 = a + b * c; // result1 will be 20 (10 + (5 * 2))
  int result2 = (a + b) * c; // result2 will be 30 ((10 + 5) * 2)
  double x = 1.0, y = 2.0;
  double result3 = pow(x,y); // pow function handles precedence internally
  std::cout << "result1: " << result1 << std::endl;
  std::cout << "result2: " << result2 << std::endl;
  std::cout << "result3: " << result3 << std::endl; // result3 will be 1.0
  return 0;
}
